<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$validDate=static function(string $v):bool{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);$e=DateTimeImmutable::getLastErrors();return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)===1&&$d!==false&&$d->format('Y-m-d')===$v&&($e===false||(!$e['warning_count']&&!$e['error_count']));};$operation=(string)($_POST['operation']??'assign');$pdo=db();
try{$pdo->beginTransaction();if($operation==='end'){$id=filter_var($_POST['assignment_id']??null,FILTER_VALIDATE_INT);$end=trim((string)($_POST['ends_on']??date('Y-m-d')));if(!$id||!$validDate($end)||$end<date('Y-m-d'))throw new DomainException('Choose a valid route end date that is today or later.');$q=$pdo->prepare("SELECT id,starts_on,status FROM transport_assignments WHERE id=:id FOR UPDATE");$q->execute(['id'=>$id]);$a=$q->fetch();if(!$a||$a['status']!=='Active')throw new DomainException('Only an active route assignment can be ended.');if($end<$a['starts_on'])throw new DomainException('End date cannot be before the route assignment start date.');$q=$pdo->prepare("UPDATE transport_assignments SET ends_on=:end,status='Completed',ended_by=:user WHERE id=:id AND status='Active'");$q->execute(['end'=>$end,'user'=>$user['id'],'id'=>$id]);audit_log('transport.assignment_ended','transport_assignments',(int)$id,['ends_on'=>$end]);$pdo->commit();$_SESSION['notice']='Transport assignment ended and kept in history.';header('Location: ../?page=transport');exit;}
if($operation!=='assign')throw new DomainException('Choose a valid transport assignment action.');$student=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT);$route=filter_var($_POST['route_id']??null,FILTER_VALIDATE_INT);$start=trim((string)($_POST['starts_on']??date('Y-m-d')));$stop=trim((string)($_POST['pickup_point']??''));if(!$student||!$route||!$validDate($start)||$start<date('Y-m-d')||$stop===''||strlen($stop)>120)throw new DomainException('Choose an active learner, route, today or future start date and pickup point.');$q=$pdo->prepare("SELECT id FROM students WHERE id=:id AND status='Active' FOR UPDATE");$q->execute(['id'=>$student]);if(!$q->fetch())throw new DomainException('Only an active learner can be assigned to transport.');$q=$pdo->prepare("SELECT r.id,r.vehicle_id,v.seat_capacity FROM transport_routes r JOIN transport_vehicles v ON v.id=r.vehicle_id AND v.status='Active' WHERE r.id=:route AND r.active=1 FOR UPDATE");$q->execute(['route'=>$route]);$r=$q->fetch();if(!$r)throw new DomainException('Choose a route with an active vehicle.');$q=$pdo->prepare("SELECT id,starts_on FROM transport_assignments WHERE student_id=:student AND status='Active' AND (ends_on IS NULL OR ends_on>=:start) ORDER BY starts_on FOR UPDATE");$q->execute(['student'=>$student,'start'=>$start]);$oldRows=$q->fetchAll();foreach($oldRows as $old){if($old['starts_on']>=$start)throw new DomainException('This learner already has a current or future route allocation overlapping that date.');$previousDay=(new DateTimeImmutable($start))->modify('-1 day')->format('Y-m-d');if($previousDay<$old['starts_on'])throw new DomainException('Choose a start date after the current route assignment begins.');$q=$pdo->prepare("UPDATE transport_assignments SET ends_on=:end,status='Completed',ended_by=:user WHERE id=:id AND status='Active'");$q->execute(['end'=>$previousDay,'user'=>$user['id'],'id'=>$old['id']]);}$q=$pdo->prepare("SELECT COUNT(*) FROM transport_assignments WHERE route_id=:route AND status='Active' AND starts_on<=:start AND (ends_on IS NULL OR ends_on>=:start)");$q->execute(['route'=>$route,'start'=>$start]);if((int)$q->fetchColumn()>=(int)$r['seat_capacity'])throw new DomainException('This route is at vehicle capacity for the requested date.');$q=$pdo->prepare('INSERT INTO transport_assignments(student_id,route_id,pickup_point,starts_on,assigned_by) VALUES(:student,:route,:stop,:start,:user)');$q->execute(['student'=>$student,'route'=>$route,'stop'=>$stop,'start'=>$start,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('transport.learner_assigned','transport_assignments',$id,['student_id'=>$student,'route_id'=>$route,'starts_on'=>$start]);$pdo->commit();$_SESSION['notice']='Learner transport route saved.';
}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Transport assignment failed: '.$e->getMessage());$_SESSION['error']='Could not save the transport assignment.';}header('Location: ../?page=transport');exit;
